import numpy as np
import numpy as np
import math
RD, RF = 0.030, 0.035
def _rule(omax, n):
    h = 2.0 * omax / n
    om = -omax + h * np.arange(n + 1)
    w = np.empty(n + 1)
    w[0] = w[-1] = 1.0
    w[1:-1:2] = 4.0
    w[2:-1:2] = 2.0
    return om, w * h / 3.0
OM, OW = _rule(300.0, 8192)
RULE = np.concatenate((OM, OW))
def _pref(om, alpha, zeta):
    z = 1j * om + alpha
    return RD * np.exp(z * zeta) / z - RF * np.exp((1.0 + z) * zeta) / (1.0 + z)
def _gauss(om, alpha, zeta, mu, sg):
    u = -om + 1j * alpha
    W = _pref(om, alpha, zeta) * np.exp(1j * u * mu - 0.5 * sg * sg * u * u)
    return np.concatenate((W.real, W.imag))
def _Phi(x):
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))
def _exact(zeta, mu, sg):
    d = (zeta - mu) / sg
    return RD * _Phi(d) - RF * math.exp(mu + 0.5 * sg * sg) * _Phi(d - sg)
K = _gauss(OM, 1.0, -0.20, 0.0, 0.30)
assert np.allclose(round(float(exercise_region_expectation(K, RULE, 1.0, 0.0)), 15), target)

